    public static CollectTaxIdStage builder() {
        return new Builder();
    }

    public interface CollectTaxIdStage {
        /**
         * <p>Whether this seller offers tax ID entry on checkout (their VAT ID setting). When <code>false</code>, hide the input — a stored <code>tax_id</code> still applies either way.</p>
         */
        CreatedAtStage collectTaxId(boolean collectTaxId);

        Builder from(CheckoutSession other);
    }

    public interface CreatedAtStage {
        /**
         * <p>When the session was created, as an ISO 8601 timestamp.</p>
         */
        CtaLabelStage createdAt(@NotNull String createdAt);
    }

    public interface CtaLabelStage {
        /**
         * <p>The verb for the button that confirms this checkout, so every surface names the act the same way: <code>pay</code>, <code>subscribe</code>, <code>start_trial</code>, <code>join_waitlist</code>, or <code>continue</code> when nothing is charged today (a free checkout, <code>setup</code> mode saving a payment method, or a transfer that charges nothing). Render your own wording for each value — this is a key, never display text — and fall back to a generic label on a value you do not recognize.</p>
         */
        DisplayCurrencyStage ctaLabel(@NotNull CheckoutSessionCtaLabel ctaLabel);
    }

    public interface DisplayCurrencyStage {
        /**
         * <p>The currency this checkout is priced AND charged in, lowercase. Seeded at create from where the buyer is; update it to one of <code>available_currencies</code> to price and charge in that currency instead.</p>
         */
        ExpiresAtStage displayCurrency(@NotNull String displayCurrency);
    }

    public interface ExpiresAtStage {
        /**
         * <p>When the session expires, as an ISO 8601 timestamp. An expired session cannot be updated or confirmed — start a new one.</p>
         */
        IdStage expiresAt(@NotNull String expiresAt);
    }

    public interface IdStage {
        /**
         * <p>Checkout session ID, prefixed <code>chs_</code>.</p>
         */
        ModeStage id(@NotNull String id);
    }

    public interface ModeStage {
        /**
         * <p><code>payment</code> charges the items at confirm; <code>setup</code> saves a payment method for later use.</p>
         */
        ObjectStage mode(@NotNull CheckoutSessionMode mode);
    }

    public interface ObjectStage {
        /**
         * <p>Always <code>checkout_session</code>.</p>
         */
        PaymentMethodRequiredStage object(@NotNull String object);
    }

    public interface PaymentMethodRequiredStage {
        /**
         * <p>Whether confirm needs a <code>confirmation_token</code>. <code>false</code> when no charge will ever take money — a free plan, a transfer of a non-renewing plan, or an applied promo code that makes every charge free, now and forever: collect no payment method there and confirm without a token. Live like every session fact: applying or removing a code can flip it, so mount your payment surface off this field, never off a zero total — a checkout that charges nothing today but something later (a trial, a first-charge-only code) stays <code>true</code>.</p>
         */
        QuoteStage paymentMethodRequired(boolean paymentMethodRequired);
    }

    public interface QuoteStage {
        /**
         * <p>The current price of the items, computed by the server on every read. Confirm charges this number while it is fresh.</p>
         */
        SellerStage quote(@NotNull CheckoutSessionQuote quote);
    }

    public interface SellerStage {
        /**
         * <p>The seller this checkout purchases from.</p>
         */
        ShowPromoCodeInputStage seller(@NotNull CheckoutSessionSeller seller);
    }

    public interface ShowPromoCodeInputStage {
        /**
         * <p>Whether to offer promo code entry on this checkout: <code>false</code> on a membership transfer, a checkout with nothing due, or a one-off purchase — no code can apply — and when the seller disabled codes for it, or none exists to enter. A code already on the session still discounts either way.</p>
         */
        StatusStage showPromoCodeInput(boolean showPromoCodeInput);
    }

    public interface StatusStage {
        /**
         * <p><code>open</code> until a confirm succeeds (<code>completed</code>) or the session ages out (<code>expired</code>). Only an <code>open</code> session can be updated or confirmed. A <code>completed</code> session whose charge later decisively dies returns to <code>open</code> with the failure on <code>last_confirm_error</code> — the same session takes the retry.</p>
         */
        _FinalStage status(@NotNull CheckoutSessionStatus status);
    }

